<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>snek — a tiny snake game</title>
<style>
  :root {
    --bg: #0f1117;
    --panel: #1a1d27;
    --panel2: #222635;
    --text: #e6e9f0;
    --muted: #8b90a0;
    --accent: #4ade80;
    --accent2: #22c55e;
    --danger: #f87171;
    --grid: #171a24;
  }
  * { box-sizing: border-box; }
  html, body { height: 100%; }
  body {
    margin: 0;
    font-family: ui-monospace, "SF Mono", "Cascadia Code", "Fira Code", Menlo, monospace;
    background: radial-gradient(1200px 800px at 50% -10%, #1b2030 0%, var(--bg) 60%);
